import{_ as t,o as s,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Fees and pricing","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/frais-tarification.md","filePath":"src/en/guide/admin/frais-tarification.md"}'),n={name:"en/guide/admin/frais-tarification.md"};function o(i,e,c,l,d,u){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="fees-and-pricing" tabindex="-1">Fees and pricing <a class="header-anchor" href="#fees-and-pricing" aria-label="Permalink to &quot;Fees and pricing&quot;">​</a></h1><p>This section covers defining the amounts families owe (fee structures) and the discounts you can grant on a case-by-case basis. Recording payments themselves is the cashier&#39;s day-to-day job — you only step in here on pricing and discounts.</p><h2 id="fee-structures" tabindex="-1">Fee structures <a class="header-anchor" href="#fee-structures" aria-label="Permalink to &quot;Fee structures&quot;">​</a></h2><p><strong>School setup → Fee Structures</strong> defines the list of fees owed by the students of a site for an academic year. A structure applies to one of three choices (<strong>Applies to</strong>):</p><ul><li><strong>The whole department</strong>: every class of the department on that site;</li><li><strong>A level</strong>: every class of that level (for instance 6e);</li><li><strong>A class</strong>: a single class (for instance 6e A).</li></ul><p>The most specific structure wins: a student is billed by their class&#39;s structure, failing that their level&#39;s, failing that their department&#39;s. You can therefore keep a department structure for the general case and add a level or class structure only where the amounts differ. A student with no matching structure at all has no amount calculated.</p><p>To create a fee structure:</p><ol><li>Click <strong>New fee structure</strong>.</li><li>Choose the <strong>Site</strong>, the <strong>Department</strong>, and the <strong>Academic year</strong>.</li><li>Under <strong>Applies to</strong>, choose the whole department, a level or a class, then the level or class concerned.</li><li>Add one or more fee items with <strong>Add a fee item</strong>, filling in the fields below for each.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Label</td><td>e.g. &quot;Tuition&quot;, &quot;Cafeteria&quot;</td></tr><tr><td>Amount</td><td>—</td></tr><tr><td>Optional</td><td>check for a service to choose (cafeteria, transport…): the parent ticks it from their space, or the cash desk from the student&#39;s record</td></tr><tr><td>Category</td><td>General, Cafeteria, or Transport</td></tr></tbody></table><p>Editing an existing fee structure lets you add, change, or remove items. A structure already in use (a payment or a chosen service) can no longer change its site, department, year or target: create a new one instead. Deleting a fee structure also permanently deletes all its items.</p><div class="info custom-block"><p class="custom-block-title">Optional services</p><p>When a level or class structure takes over from a department structure, the optional services the students concerned already chose move to the new structure if it has an equivalent service (same category and same label). A service the new structure doesn&#39;t offer is removed.</p></div><p>When a new year is prepared, level and class structures are copied like the others; a class structure goes to the class of the same name on the same site, and isn&#39;t copied if that class doesn&#39;t exist yet.</p><h2 id="discounts" tabindex="-1">Discounts <a class="header-anchor" href="#discounts" aria-label="Permalink to &quot;Discounts&quot;">​</a></h2><p>Discounts aren&#39;t managed on the fee structure itself, but on a specific student&#39;s billing: <strong>Finances → Billing</strong>, search for the student, click <strong>View</strong> to open their billing record.</p><p>On that screen, you alone (as an administrator — the cashier can only record payments) can grant or remove a discount:</p><p>To grant a discount:</p><ol><li>In the &quot;Discounts&quot; section, fill in the <strong>Label</strong> of the discount.</li><li>Choose the <strong>Type</strong>: Fixed amount or Percentage.</li><li>Fill in the matching <strong>Value</strong> and, optionally, a <strong>Reason</strong>.</li><li>Click <strong>Grant discount</strong>.</li></ol><p>Each discount granted shows the name of the administrator who created it. The <strong>Delete</strong> button next to a discount removes it permanently — the student&#39;s outstanding balance is recalculated immediately.</p>',18)])])}const p=t(n,[["render",o]]);export{g as __pageData,p as default};
